const STYLE_BLOCK = `
@import url('https://fonts.googleapis.com/css2?family=Staatliches&family=Work+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

.hn-root {
  --ink: #F2F9FB;
  --ink-soft: #E6F1F5;
  --panel: #FFFFFF;
  --panel-raised: #EAF4F8;
  --line: #C7DEE8;
  --line-soft: #D8E9F0;
  --teal: #0E86AC;
  --teal-soft: #0A5F7C;
  --amber: #E2A63C;
  --rust: #D9552B;
  --foam: #123047;
  --foam-dim: #4F7186;
  --ink-text: #123047;
  --font-display: 'Staatliches', sans-serif;
  --font-body: 'Work Sans', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;
  background: var(--ink);
  color: var(--foam);
  font-family: var(--font-body);
  min-height: 100vh;
}
.hn-root * { box-sizing: border-box; }
.hn-display { font-family: var(--font-display); letter-spacing: 0.02em; text-transform: uppercase; }
.hn-mono { font-family: var(--font-mono); }
.hn-focus:focus-visible { outline: 2px solid var(--teal-soft); outline-offset: 3px; }
.hn-line { background: linear-gradient(90deg, transparent, var(--line), transparent); height: 1px; border: none; }
.hn-strand { stroke-dasharray: 400; stroke-dashoffset: 400; animation: hn-cast 1.4s ease-out forwards; }
@keyframes hn-cast { to { stroke-dashoffset: 0; } }
.hn-badge-spin { animation: hn-spin-in 1.1s cubic-bezier(.2,.8,.2,1) both; }
@keyframes hn-spin-in { from { opacity: 0; transform: rotate(-25deg) scale(.7); } to { opacity: 1; transform: rotate(0deg) scale(1); } }
.hn-rise { animation: hn-rise-up .7s ease both; }
@keyframes hn-rise-up { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: translateY(0); } }
@media (prefers-reduced-motion: reduce) {
  .hn-strand, .hn-badge-spin, .hn-rise { animation: none !important; opacity: 1 !important; stroke-dashoffset: 0 !important; transform: none !important; }
}
.hn-card:hover { border-color: var(--teal); transform: translateY(-2px); box-shadow: 0 16px 30px -14px rgba(14,134,172,0.28); }
.hn-card { transition: border-color .2s ease, transform .2s ease, box-shadow .2s ease; box-shadow: 0 1px 3px rgba(18,48,71,0.06); }
.hn-swatch:hover { transform: scale(1.06); }
.hn-swatch { transition: transform .15s ease, border-color .15s ease; }
.hn-scrollbar::-webkit-scrollbar { width: 6px; }
.hn-scrollbar::-webkit-scrollbar-thumb { background: var(--line); border-radius: 4px; }
`;

