function HNLogo({ width = 150, className = "" }) {
  return (
    <img
      src={LOGO_SRC}
      alt="HN Lures"
      width={width}
      style={{ width, height: "auto", display: "block" }}
      className={className}
    />
  );
}

const HEAD_PATHS = {
  slim: <ellipse cx="70" cy="42" rx="15" ry="32" />,
  bullet: <ellipse cx="70" cy="42" rx="22" ry="28" />,
  pusher: <path d="M48,18 Q70,6 92,18 L90,58 Q70,72 50,58 Z" />,
  broad: <ellipse cx="70" cy="40" rx="29" ry="24" />,
  cupped: <path d="M40,20 Q70,2 100,20 L95,62 Q70,80 45,62 Z" />,
};

function LureIcon({ shape = "bullet", colors = ["#19A79C", "#E8A33D"], size = 120, strands = 11, animate = false }) {
  const gid = useRef(`hg-${Math.random().toString(36).slice(2, 8)}`).current;
  const [c1, c2] = colors;
  const items = Array.from({ length: strands });
  return (
    <svg viewBox="0 0 140 260" width={size} height={(size * 260) / 140} style={{ overflow: "visible" }}>
      <defs>
        <linearGradient id={gid} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#F3EFE4" />
          <stop offset="100%" stopColor="#95A9BC" />
        </linearGradient>
      </defs>
      <g transform="translate(0,6)">
        {items.map((_, i) => {
          const t = i / (strands - 1);
          const xOff = (t - 0.5) * 56;
          const color = i % 2 === 0 ? c1 : c2;
          const d = `M70,58 C${70 + xOff * 0.35},112 ${70 + xOff * 0.9},172 ${70 + xOff * 1.25},238`;
          return (
            <path
              key={i}
              d={d}
              stroke={color}
              strokeWidth="6.5"
              fill="none"
              strokeLinecap="round"
              opacity={0.92}
              className={animate ? "hn-strand" : undefined}
              style={animate ? { animationDelay: `${i * 0.03}s` } : undefined}
            />
          );
        })}
        <g fill={`url(#${gid})`} stroke="var(--line)" strokeWidth="1">
          {HEAD_PATHS[shape]}
        </g>
        <circle cx="61" cy="36" r="2.6" fill="var(--ink)" />
      </g>
    </svg>
  );
}

