function Header({ page, setPage, cartCount, onCart }) {
  const [open, setOpen] = useState(false);
  const links = [
    ["home", "Home"], ["shop", "Shop"], ["gallery", "Gallery"], ["about", "About"], ["contact", "Contact"],
  ];
  const go = (p) => { setPage(p); setOpen(false); };
  return (
    <header style={{
      position: "sticky", top: 0, zIndex: 40, background: "rgba(242,249,251,0.88)",
      backdropFilter: "blur(6px)", borderBottom: "1px solid var(--line-soft)",
      boxShadow: "0 1px 0 rgba(18,48,71,0.04)",
    }}>
      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "14px 20px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <button className="hn-focus" onClick={() => go("home")} style={{ display: "flex", alignItems: "center", gap: 10, background: "none", border: "none", cursor: "pointer" }}>
          <HNLogo width={128} />
        </button>

        <nav style={{ display: "none", gap: 28 }} className="hn-desktop-nav">
          {links.map(([id, label]) => (
            <button
              key={id} onClick={() => go(id)} className="hn-focus hn-mono"
              style={{
                background: "none", border: "none", cursor: "pointer", fontSize: 13, letterSpacing: 1.5,
                color: page === id ? "var(--amber)" : "var(--foam-dim)", padding: "6px 0", textTransform: "uppercase",
              }}
            >
              {label}
            </button>
          ))}
        </nav>

        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <button onClick={onCart} className="hn-focus" style={{
            position: "relative", background: "var(--panel-raised)", border: "1px solid var(--line)",
            borderRadius: 6, padding: "9px 11px", cursor: "pointer", color: "var(--foam)",
          }}>
            <ShoppingBag size={18} />
            {cartCount > 0 && (
              <span className="hn-mono" style={{
                position: "absolute", top: -6, right: -6, background: "var(--rust)", color: "#fff",
                borderRadius: 999, fontSize: 10, minWidth: 18, height: 18, display: "flex",
                alignItems: "center", justifyContent: "center", padding: "0 4px",
              }}>{cartCount}</span>
            )}
          </button>
          <button onClick={() => setOpen(!open)} className="hn-focus hn-mobile-toggle" style={{
            background: "var(--panel-raised)", border: "1px solid var(--line)", borderRadius: 6,
            padding: "9px 11px", cursor: "pointer", color: "var(--foam)",
          }}>
            {open ? <X size={18} /> : <Menu size={18} />}
          </button>
        </div>
      </div>

      {open && (
        <div className="hn-mobile-nav" style={{ borderTop: "1px solid var(--line-soft)", padding: "10px 20px 18px", display: "flex", flexDirection: "column", gap: 4 }}>
          {links.map(([id, label]) => (
            <button
              key={id} onClick={() => go(id)} className="hn-focus hn-mono"
              style={{
                textAlign: "left", background: "none", border: "none", cursor: "pointer", padding: "10px 4px",
                fontSize: 14, letterSpacing: 1, color: page === id ? "var(--amber)" : "var(--foam)",
              }}
            >{label}</button>
          ))}
        </div>
      )}

      <style>{`
        @media (min-width: 860px) {
          .hn-desktop-nav { display: flex !important; }
          .hn-mobile-toggle, .hn-mobile-nav { display: none !important; }
        }
      `}</style>
    </header>
  );
}

/* ------------------------------------------------------------------ */
/*  CART DRAWER                                                        */
/* ------------------------------------------------------------------ */
function CartDrawer({ open, onClose, cart, setCart, goCheckout }) {
  const total = cart.reduce((s, it) => s + it.price * it.qty, 0);
  const updateQty = (idx, delta) => {
    setCart((prev) => prev.map((it, i) => (i === idx ? { ...it, qty: Math.max(1, it.qty + delta) } : it)));
  };
  const remove = (idx) => setCart((prev) => prev.filter((_, i) => i !== idx));

  if (!open) return null;
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 60, display: "flex", justifyContent: "flex-end" }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(6,10,16,0.6)" }} />
      <div className="hn-scrollbar" style={{
        position: "relative", width: "min(400px, 92vw)", height: "100%", background: "var(--panel)",
        borderLeft: "1px solid var(--line)", display: "flex", flexDirection: "column", overflowY: "auto",
        boxShadow: "-12px 0 40px rgba(18,48,71,0.18)",
      }}>
        <div style={{ padding: "20px 20px 14px", borderBottom: "1px solid var(--line)", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span className="hn-display" style={{ fontSize: 20 }}>Your Order</span>
          <button onClick={onClose} className="hn-focus" style={{ background: "none", border: "none", color: "var(--foam)", cursor: "pointer" }}><X size={20} /></button>
        </div>

        <div style={{ flex: 1, padding: 18, display: "flex", flexDirection: "column", gap: 14 }}>
          {cart.length === 0 && (
            <p style={{ color: "var(--foam-dim)", fontSize: 14 }}>Your tackle box is empty. Head to the shop and build a lure.</p>
          )}
          {cart.map((it, idx) => (
            <div key={idx} style={{ display: "flex", gap: 12, borderBottom: "1px solid var(--line-soft)", paddingBottom: 14 }}>
              <div style={{ background: "var(--panel-raised)", borderRadius: 6, padding: 6 }}>
                <LureIcon shape={it.shape} colors={it.colors} size={44} strands={7} />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 600, fontSize: 14 }}>{it.name}</div>
                <div className="hn-mono" style={{ fontSize: 11.5, color: "var(--foam-dim)" }}>{it.skirtName}</div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 8 }}>
                  <button onClick={() => updateQty(idx, -1)} className="hn-focus" style={{ background: "var(--panel-raised)", border: "1px solid var(--line)", borderRadius: 4, color: "var(--foam)", cursor: "pointer", padding: 2 }}><Minus size={12} /></button>
                  <span className="hn-mono" style={{ fontSize: 12, width: 16, textAlign: "center" }}>{it.qty}</span>
                  <button onClick={() => updateQty(idx, 1)} className="hn-focus" style={{ background: "var(--panel-raised)", border: "1px solid var(--line)", borderRadius: 4, color: "var(--foam)", cursor: "pointer", padding: 2 }}><Plus size={12} /></button>
                  <button onClick={() => remove(idx)} className="hn-focus" style={{ marginLeft: "auto", background: "none", border: "none", color: "var(--rust)", cursor: "pointer" }}><Trash2 size={14} /></button>
                </div>
              </div>
              <div className="hn-mono" style={{ fontSize: 13 }}>{money(it.price * it.qty)}</div>
            </div>
          ))}
        </div>

        {cart.length > 0 && (
          <div style={{ padding: 18, borderTop: "1px solid var(--line)" }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12, fontFamily: "var(--font-mono)" }}>
              <span style={{ color: "var(--foam-dim)" }}>Subtotal</span>
              <span style={{ fontSize: 16 }}>{money(total)}</span>
            </div>
            <Button full variant="primary" icon={ArrowRight} onClick={goCheckout}>Checkout</Button>
          </div>
        )}
      </div>
    </div>
  );
}

