function PhotoBand({ src, eyebrow, title, sub, height = "56vh" }) {
  return (
    <section style={{ position: "relative", height, minHeight: 320, overflow: "hidden" }}>
      <img src={src} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
      <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(6,16,26,0.15) 0%, rgba(6,16,26,0.55) 70%, rgba(6,16,26,0.75) 100%)" }} />
      <div style={{ position: "relative", height: "100%", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: "0 20px" }}>
        {eyebrow && <div className="hn-mono" style={{ color: "#8FE0D8", fontSize: 12, letterSpacing: 3, marginBottom: 10 }}>{eyebrow}</div>}
        <h2 className="hn-display" style={{ color: "#FFFFFF", fontSize: "clamp(28px,5vw,48px)", marginBottom: sub ? 10 : 0 }}>{title}</h2>
        {sub && <p style={{ color: "rgba(255,255,255,0.85)", maxWidth: 480, fontSize: 15 }}>{sub}</p>}
      </div>
    </section>
  );
}

