      {/* TRUST STRIP */}
      <section style={{ borderBottom: "1px solid var(--line-soft)", background: "var(--ink-soft)" }}>
        <div style={{ maxWidth: 1180, margin: "0 auto", padding: "22px 20px", display: "grid", gridTemplateColumns: "repeat(2,1fr)", gap: 18 }} className="hn-trust-grid">
          {["25+ Years Hand-Tied", "Father & Son Built", "Hand-Poured Heads", "Custom Colour Combos"].map((t) => (
            <div key={t} style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <Check size={16} color="var(--teal)" />
              <span className="hn-mono" style={{ fontSize: 12.5, color: "var(--foam-dim)", letterSpacing: 0.4 }}>{t}</span>
            </div>
          ))}
        </div>
        <style>{`@media (min-width: 760px) { .hn-trust-grid { grid-template-columns: repeat(4,1fr) !important; } }`}</style>
      </section>

      {/* FEATURED MODELS */}
      <section style={{ maxWidth: 1180, margin: "0 auto", padding: "70px 20px" }}>
        <SectionEyebrow>The Range</SectionEyebrow>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 12, marginBottom: 34 }}>
          <h2 className="hn-display" style={{ fontSize: "clamp(28px,4vw,42px)" }}>Six heads. One shed.</h2>
          <button onClick={() => setPage("shop")} className="hn-focus hn-mono" style={{ background: "none", border: "none", color: "var(--teal)", cursor: "pointer", display: "flex", alignItems: "center", gap: 6, fontSize: 13 }}>
            View full shop <ChevronRight size={14} />
          </button>
        </div>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 18 }}>
          {PRODUCTS.map((p) => (
            <button
              key={p.id} onClick={() => setPage("shop")}
              className="hn-focus hn-card"
              style={{
                background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 10,
                padding: 14, textAlign: "left", cursor: "pointer", color: "var(--foam)", overflow: "hidden",
              }}
            >
              {p.photos[0] ? (
                <img src={p.photos[0]} alt={p.name} style={{ width: "100%", aspectRatio: "3/4", objectFit: "cover", borderRadius: 6, marginBottom: 10 }} />
              ) : (
                <div style={{ display: "flex", justifyContent: "center", padding: "10px 0" }}>
                  <LureIcon shape={p.shape} colors={["#9FB4C7", "#E8A33D"]} size={80} strands={9} />
                </div>
              )}
              <div className="hn-display" style={{ fontSize: 18 }}>{p.name}</div>
              <div className="hn-mono" style={{ fontSize: 11.5, color: "var(--foam-dim)" }}>{p.size} \u00b7 {money(p.price)}</div>
            </button>
          ))}
        </div>
      </section>

