/*  ABOUT PAGE                                                         */
/* ------------------------------------------------------------------ */
function About({ setPage }) {
  return (
    <div style={{ maxWidth: 1180, margin: "0 auto", padding: "50px 20px 90px" }}>
      <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 40, marginBottom: 60 }} className="hn-about-grid">
        <div>
          <SectionEyebrow>Our Story</SectionEyebrow>
          <h1 className="hn-display" style={{ fontSize: "clamp(30px,5vw,48px)", marginBottom: 20 }}>Twenty-five years in the shed.</h1>
          <p style={{ color: "var(--foam-dim)", lineHeight: 1.75, marginBottom: 16 }}>
            HN Lures started as one hand pouring resin heads in a Queensland garage, chasing a better run and a
            better hookup rate than anything on the shelf. Two and a half decades on, the recipe hasn't changed much
            \u2014 it's still poured, tuned and tied by hand \u2014 but now it's a father-and-son operation, and for the
            first time the lures are available outside the immediate crew.
          </p>
          <p style={{ color: "var(--foam-dim)", lineHeight: 1.75, marginBottom: 26 }}>
            Every head that leaves the shed has been bench-tested. Every skirt is tied strand by strand to order.
            Nothing goes out the door until it's proofed the way it would be for our own spread.
          </p>
          <Button variant="outline" icon={ArrowRight} onClick={() => setPage("shop")}>See the Range</Button>
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 14, padding: 40 }}>
          <HNLogo width={340} />
        </div>
      </div>

      <div style={{ borderTop: "1px solid var(--line-soft)", paddingTop: 50 }}>
        <SectionEyebrow>What We Won't Compromise On</SectionEyebrow>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px,1fr))", gap: 24 }}>
          {[
            ["Hand-poured, every time", "No injection moulding. Small batches, poured and cured by hand."],
            ["Bench-tested action", "Every head is run before it's tied \u2014 if it doesn't track true, it doesn't go out."],
            ["Built to your combo", "Any head, any skirt colour on our list. If you've got a combo in mind, ask."],
          ].map(([t, d]) => (
            <div key={t}>
              <div className="hn-display" style={{ fontSize: 18, marginBottom: 8, color: "var(--teal)" }}>{t}</div>
              <p style={{ color: "var(--foam-dim)", fontSize: 14, lineHeight: 1.6 }}>{d}</p>
            </div>
          ))}
        </div>
      </div>

      <style>{`@media (min-width: 860px) { .hn-about-grid { grid-template-columns: 1.2fr 0.8fr !important; align-items: center; } }`}</style>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  CONTACT PAGE                                                       */
/* ------------------------------------------------------------------ */
function Contact() {
  const [form, setForm] = useState({ name: "", email: "", message: "" });
  const [sent, setSent] = useState(false);

  const submit = (e) => {
    e.preventDefault();
    setSent(true);
  };

  return (
    <div style={{ maxWidth: 1180, margin: "0 auto", padding: "50px 20px 90px" }}>
      <SectionEyebrow>Get In Touch</SectionEyebrow>
      <h1 className="hn-display" style={{ fontSize: "clamp(30px,5vw,48px)", marginBottom: 10 }}>Ask about a combo.</h1>
      <p style={{ color: "var(--foam-dim)", maxWidth: 560, marginBottom: 44 }}>
        Custom colour request, bulk order, or just want to know what's biting on \u2014 flick us a message.
      </p>

      <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 40 }} className="hn-contact-grid">
        <form onSubmit={submit} style={{ background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 14, padding: 28 }}>
          {sent ? (
            <div style={{ textAlign: "center", padding: "30px 10px" }}>
              <Check size={34} color="var(--teal)" style={{ marginBottom: 12 }} />
              <div className="hn-display" style={{ fontSize: 20, marginBottom: 8 }}>Message sent.</div>
              <p style={{ color: "var(--foam-dim)", fontSize: 14 }}>We'll get back to you as soon as we're off the water.</p>
            </div>
          ) : (
            <>
              <Field label="Name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} />
              <Field label="Email" type="email" value={form.email} onChange={(v) => setForm({ ...form, email: v })} />
              <Field label="Message" textarea value={form.message} onChange={(v) => setForm({ ...form, message: v })} />
              <Button type="submit" full variant="primary" icon={ArrowRight}>Send Message</Button>
            </>
          )}
        </form>

        <div>
          <div style={{ display: "flex", flexDirection: "column", gap: 22 }}>
            <ContactRow icon={Mail} label="Email" value="Ventricfishing@gmail.com" href="mailto:Ventricfishing@gmail.com" />
            <ContactRow icon={Instagram} label="Instagram" value="@hn_lures" href="https://www.instagram.com/hn_lures/" />
            <ContactRow icon={Facebook} label="Facebook" value="Ventric" />
            <ContactRow icon={MapPin} label="Based in" value="Brisbane, Queensland" />
          </div>
          <hr className="hn-line" style={{ margin: "28px 0" }} />
          <div className="hn-display" style={{ fontSize: 16, marginBottom: 10 }}>Before you ask</div>
          <p style={{ color: "var(--foam-dim)", fontSize: 13.5, lineHeight: 1.7 }}>
            Custom combos are made to order, so give us a shout before you need them for a trip. Bulk and
            club orders are welcome \u2014 just include a rough quantity in your message.
          </p>
        </div>
      </div>

      <style>{`@media (min-width: 860px) { .hn-contact-grid { grid-template-columns: 1.1fr 0.9fr !important; } }`}</style>
    </div>
  );
}

function Field({ label, value, onChange, type = "text", textarea }) {
  const common = {
    width: "100%", background: "var(--panel-raised)", border: "1px solid var(--line)", borderRadius: 6,
    padding: "11px 12px", color: "var(--foam)", fontFamily: "var(--font-body)", fontSize: 14, marginBottom: 18,
  };
  return (
    <label style={{ display: "block" }}>
      <span className="hn-mono" style={{ fontSize: 11, color: "var(--foam-dim)", letterSpacing: 1, display: "block", marginBottom: 6 }}>{label.toUpperCase()}</span>
      {textarea ? (
        <textarea required rows={4} value={value} onChange={(e) => onChange(e.target.value)} style={{ ...common, resize: "vertical" }} className="hn-focus" />
      ) : (
        <input required type={type} value={value} onChange={(e) => onChange(e.target.value)} style={common} className="hn-focus" />
      )}
    </label>
  );
}

function ContactRow({ icon: Icon, label, value, href }) {
  const content = (
    <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
      <div style={{ background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 8, padding: 10, color: "var(--teal)" }}><Icon size={17} /></div>
      <div>
        <div className="hn-mono" style={{ fontSize: 10.5, color: "var(--foam-dim)", letterSpacing: 1 }}>{label.toUpperCase()}</div>
        <div style={{ fontSize: 14.5 }}>{value}</div>
      </div>
    </div>
  );
  return href ? <a href={href} target="_blank" rel="noopener noreferrer" style={{ textDecoration: "none", color: "var(--foam)" }}>{content}</a> : content;
}

/* ------------------------------------------------------------------ */
/*  CHECKOUT PAGE (MOCK)                                                */
/* ------------------------------------------------------------------ */
function Checkout({ cart, setCart, setPage }) {
  const [form, setForm] = useState({ name: "", email: "", address: "", suburb: "", postcode: "" });
  const [placed, setPlaced] = useState(false);
  const [orderNo] = useState(() => `HN-${Math.floor(1000 + Math.random() * 9000)}`);
  const total = cart.reduce((s, it) => s + it.price * it.qty, 0);

  const place = (e) => {
    e.preventDefault();
    setPlaced(true);
    setCart([]);
  };

  if (placed) {
    return (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: "90px 20px", textAlign: "center" }}>
        <Check size={44} color="var(--teal)" style={{ marginBottom: 18 }} />
        <h1 className="hn-display" style={{ fontSize: 32, marginBottom: 10 }}>Order {orderNo} placed.</h1>
        <p style={{ color: "var(--foam-dim)", marginBottom: 8, lineHeight: 1.7 }}>
          This is a demo checkout \u2014 no payment has been taken. In a live store this is where confirmation and
          payment would run through a real gateway.
        </p>
        <p style={{ color: "var(--foam-dim)", marginBottom: 30, lineHeight: 1.7 }}>
          A confirmation would normally be sent to <strong style={{ color: "var(--foam)" }}>{form.email || "your email"}</strong>.
        </p>
        <Button variant="primary" icon={ArrowRight} onClick={() => setPage("shop")}>Back to Shop</Button>
      </div>
    );
  }

  if (cart.length === 0) {
    return (
      <div style={{ maxWidth: 640, margin: "0 auto", padding: "90px 20px", textAlign: "center" }}>
        <h1 className="hn-display" style={{ fontSize: 28, marginBottom: 12 }}>Nothing in your order yet.</h1>
        <Button variant="primary" onClick={() => setPage("shop")}>Go to Shop</Button>
      </div>
    );
  }

  return (
    <div style={{ maxWidth: 980, margin: "0 auto", padding: "50px 20px 90px" }}>
      <div style={{ marginBottom: 8 }}><Pill>Demo checkout \u2014 no payment processed</Pill></div>
      <h1 className="hn-display" style={{ fontSize: "clamp(28px,5vw,40px)", margin: "14px 0 34px" }}>Checkout</h1>

      <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 36 }} className="hn-checkout-grid">
        <form onSubmit={place} style={{ background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 14, padding: 26 }}>
          <div className="hn-mono" style={{ fontSize: 12, color: "var(--teal)", letterSpacing: 2, marginBottom: 16 }}>SHIPPING DETAILS</div>
          <Field label="Full name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} />
          <Field label="Email" type="email" value={form.email} onChange={(v) => setForm({ ...form, email: v })} />
          <Field label="Address" value={form.address} onChange={(v) => setForm({ ...form, address: v })} />
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
            <Field label="Suburb" value={form.suburb} onChange={(v) => setForm({ ...form, suburb: v })} />
            <Field label="Postcode" value={form.postcode} onChange={(v) => setForm({ ...form, postcode: v })} />
          </div>

          <div className="hn-mono" style={{ fontSize: 12, color: "var(--teal)", letterSpacing: 2, margin: "10px 0 16px" }}>PAYMENT</div>
          <div style={{ border: "1px dashed var(--line)", borderRadius: 8, padding: 16, marginBottom: 22, color: "var(--foam-dim)", fontSize: 13 }}>
            Payment method selection would go here (card / PayPal / etc). This build is a UI mock only \u2014 nothing
            is charged.
          </div>
          <Button type="submit" full variant="primary" icon={ArrowRight}>Place Demo Order</Button>
        </form>

        <div>
          <div style={{ background: "var(--panel)", border: "1px solid var(--line)", borderRadius: 14, padding: 22 }}>
            <div className="hn-mono" style={{ fontSize: 12, color: "var(--teal)", letterSpacing: 2, marginBottom: 16 }}>ORDER SUMMARY</div>
            {cart.map((it, i) => (
              <div key={i} style={{ display: "flex", justifyContent: "space-between", gap: 10, marginBottom: 10, fontSize: 13.5 }}>
                <span>{it.name} \u00d7{it.qty} <span style={{ color: "var(--foam-dim)" }}>({it.skirtName})</span></span>
                <span className="hn-mono">{money(it.price * it.qty)}</span>
              </div>
            ))}
            <hr className="hn-line" style={{ margin: "14px 0" }} />
            <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "var(--font-display)", fontSize: 20 }}>
              <span>Total</span><span>{money(total)}</span>
            </div>
          </div>
        </div>
      </div>

      <style>{`@media (min-width: 860px) { .hn-checkout-grid { grid-template-columns: 1.3fr 1fr !important; align-items: start; } }`}</style>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/*  FOOTER                                                              */
/* ------------------------------------------------------------------ */
function Footer({ setPage }) {
  return (
    <footer style={{ borderTop: "1px solid var(--line-soft)", background: "var(--ink-soft)" }}>
      <div style={{ maxWidth: 1180, margin: "0 auto", padding: "50px 20px 30px", display: "grid", gridTemplateColumns: "1fr", gap: 32 }} className="hn-footer-grid">
        <div>
          <div style={{ marginBottom: 12 }}>
            <HNLogo width={130} />
          </div>
          <p style={{ color: "var(--foam-dim)", fontSize: 13, maxWidth: 260, lineHeight: 1.6 }}>
            Hand-poured, hand-tied game lures. Father-and-son made in Brisbane, Queensland.
          </p>
        </div>
        <div>
          <div className="hn-mono" style={{ fontSize: 11, letterSpacing: 1.5, color: "var(--foam-dim)", marginBottom: 12 }}>SITE</div>
          {["home", "shop", "gallery", "about", "contact"].map((p) => (
            <button key={p} onClick={() => setPage(p)} className="hn-focus" style={{ display: "block", background: "none", border: "none", color: "var(--foam)", cursor: "pointer", padding: "5px 0", fontSize: 13.5, textTransform: "capitalize" }}>{p}</button>
          ))}
        </div>
        <div>
          <div className="hn-mono" style={{ fontSize: 11, letterSpacing: 1.5, color: "var(--foam-dim)", marginBottom: 12 }}>CONTACT</div>
          <a href="mailto:Ventricfishing@gmail.com" style={{ display: "block", color: "var(--foam)", fontSize: 13.5, marginBottom: 6, textDecoration: "none" }}>Ventricfishing@gmail.com</a>
          <a href="https://www.instagram.com/hn_lures/" target="_blank" rel="noopener noreferrer" style={{ display: "block", color: "var(--foam)", fontSize: 13.5, marginBottom: 6, textDecoration: "none" }}>Instagram \u2014 @hn_lures</a>
          <span style={{ display: "block", color: "var(--foam)", fontSize: 13.5 }}>Facebook \u2014 Ventric</span>
        </div>
      </div>
      <div style={{ borderTop: "1px solid var(--line-soft)", padding: "16px 20px", textAlign: "center", color: "var(--foam-dim)", fontSize: 12 }}>
        \u00a9 {new Date().getFullYear()} HN Lures. All rights reserved.
      </div>
      <style>{`@media (min-width: 760px) { .hn-footer-grid { grid-template-columns: 1.4fr 1fr 1fr !important; } }`}</style>
    </footer>
  );
}

/* ------------------------------------------------------------------ */
/*  APP                                                                 */
/* ------------------------------------------------------------------ */
export default function App() {
  const [page, setPage] = useState("home");
  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);

  useEffect(() => { window.scrollTo(0, 0); }, [page]);

  const addToCart = (item) => setCart((prev) => [...prev, item]);
  const cartCount = cart.reduce((s, it) => s + it.qty, 0);

  const pages = {
    home: <Home setPage={setPage} />,
    shop: <Shop addToCart={addToCart} />,
    gallery: <Gallery />,
    about: <About setPage={setPage} />,
    contact: <Contact />,
    checkout: <Checkout cart={cart} setCart={setCart} setPage={setPage} />,
  };

  return (
    <div className="hn-root">
      <style>{STYLE_BLOCK}</style>
      <Header page={page} setPage={setPage} cartCount={cartCount} onCart={() => setCartOpen(true)} />
      {pages[page] || pages.home}
      <Footer setPage={setPage} />
      <CartDrawer
        open={cartOpen}
        onClose={() => setCartOpen(false)}
        cart={cart}
        setCart={setCart}
        goCheckout={() => { setCartOpen(false); setPage("checkout"); }}
      />
    </div>
  );
}
